import{Bt as e,It as t,St as n,bt as r,gt as i,nt as a,xt as o,yt as s}from"./chunks/framework.D2FS3J_H.js";var c=JSON.parse(`{"title":"UML Sequence Diagram","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/sequence.md","filePath":"docs/sequence.md"}`),l={name:`docs/sequence.md`};function u(a,c,l,u,d,f){let p=e(`EmbeddedHylimoEditor`),m=e(`DiagramExample`);return t(),s(`div`,null,[c[0]||=r(`<h1 id="uml-sequence-diagram" tabindex="-1">UML Sequence Diagram <a class="header-anchor" href="#uml-sequence-diagram" aria-label="Permalink to “UML Sequence Diagram”">​</a></h1><p>To create a UML sequence diagram, one uses the <code>sequenceDiagram</code> diagram function:</p><div class="language-hyl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">HyLiMo</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sequenceDiagram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    // define elements</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>In contrast to the other diagram types, the elements of a sequence diagram are not positioned by hand. Since a sequence diagram models <strong>when</strong> (and where) something happens, it is defined in the order in which it happens: participants are placed on the x axis in the order in which they are declared, and everything else is placed on the y axis in the order in which it is declared. In other words: order matters. The diagram always knows only the currently available information and nothing on top, which is what makes sequence diagrams defined in HyLiMo maintainable: inserting an interaction moves everything after it down, without having to touch a single coordinate.</p><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to “Terminology”">​</a></h2><p>In a sequence diagram, we have the following concepts:</p><ul><li>Participant: a component that &quot;participates&quot; in the diagram, so something/someone whose behavior should be modeled. It can be a <a href="#participant"><code>participant</code></a>, an <a href="#instance"><code>instance</code></a>, an <a href="#actor"><code>actor</code></a> or a <a href="#component"><code>component</code></a></li><li>Lifeline: the entire duration a participant is alive, symbolized by the dotted line downwards</li><li>Activity indicator: the time a participant is active, visualized by a white rectangle on the lifeline</li><li>Message: arrow between two participants at specific y positions with a semantic meaning</li><li>Frame: a box around a section of the diagram. Can optionally contain a name (i.e. <code>if</code>, <code>while</code>), and sub compartments (fragments)</li></ul><h2 id="elements" tabindex="-1">Elements <a class="header-anchor" href="#elements" aria-label="Permalink to “Elements”">​</a></h2><p>All participants are declared first, in the order in which they should appear from left to right:</p>`,9),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Bob%22)%0A%20%20%20%20instance(%22Shop%22)%0A%20%20%20%20actor(%22Admin%22)%0A%20%20%20%20component(%22Shop-Frontend%22)%0A%7D%0A`}),c[1]||=i(`p`,null,`Participant names are registered as variables if they did not exist already. In case they existed already, the existing name takes precedence. If their name is already used by something else, you can assign the result of these functions to a variable of your own choosing:`,-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20Bob%20%3D%20true%0A%20%20%20%20user%20%3D%20participant(%22Bob%22)%0A%20%20%20%20participant(%22Charlie%22)%0A%20%20%20%20user%20--%3E%20Charlie%0A%7D%0A`}),c[2]||=i(`h3`,{id:`participant`,tabindex:`-1`},[i(`code`,null,`participant`),o(),i(`a`,{class:`header-anchor`,href:`#participant`,"aria-label":`Permalink to “participant”`},`​`)],-1),c[3]||=i(`p`,null,[o(`Creates a participant, which is an abstract concept of someone who participates in the diagram. The name is not underlined, and it can be given a class name, which is rendered as `),i(`code`,null,`name:Class`),o(`:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22User%22)%0A%20%20%20%20participant(%22bob%22%2C%20%22User%22)%0A%7D%0A`}),c[4]||=r(`<p><strong>params</strong>:</p><ul><li>0: the optional name of the participant, if not given, the second parameter must be provided</li><li>1: the optional class name of this participant</li><li>2: the callback function of this participant</li><li><code>keywords</code>: the keywords of the participant</li><li><code>below</code>: the optional participant below which this participant should be placed. If set, this participant will have the same x coordinate as the given value and the y coordinate of the current position</li><li><code>at</code>: the absolute y position where to create the participant. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li><li><code>margin</code>: horizontal margin between this and the previous participant. Defaults to <code>participantMargin</code></li></ul><p><strong>returns</strong>: The created participant</p><p>With <code>at</code> and <code>after</code>, the creation of a participant can be postponed, which is how object creation is expressed:</p>`,4),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22%2C%20after%20%3D%2020)%0A%20%20%20%20delay(20)%0A%7D%0A`}),c[5]||=i(`h3`,{id:`instance`,tabindex:`-1`},[i(`code`,null,`instance`),o(),i(`a`,{class:`header-anchor`,href:`#instance`,"aria-label":`Permalink to “instance”`},`​`)],-1),c[6]||=i(`p`,null,`Creates an instance, a participant with an underlined name and support for values:`,-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20instance(%22cart%22%2C%20%22Cart%22)%20%7B%0A%20%20%20%20%20%20%20%20values%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20items%20%3D%203%0A%20%20%20%20%20%20%20%20%20%20%20%20total%20%3D%2042.5%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[7]||=r(`<p><strong>params</strong>:</p><ul><li>0: the optional name of the instance, if not given, the second parameter must be provided</li><li>1: the optional class name of this instance</li><li>2: the callback function of this instance</li><li><code>keywords</code>: the keywords of the instance</li><li><code>below</code>: the optional participant below which this instance should be placed. If set, this instance will have the same x coordinate as the given value and the y coordinate of the current position</li><li><code>at</code>: the absolute y position where to create the instance. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li><li><code>margin</code>: horizontal margin between this and the previous instance. Defaults to <code>participantMargin</code></li></ul><p><strong>returns</strong>: The created instance</p><h3 id="actor" tabindex="-1"><code>actor</code> <a class="header-anchor" href="#actor" aria-label="Permalink to “actor”">​</a></h3><p>Creates a stickman figure symbolizing a user:</p>`,5),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20actor(%22Admin%22)%0A%7D%0A`}),c[8]||=r(`<p><strong>params</strong>:</p><ul><li>0: the name of the actor</li><li>1: the optional class name of this actor, or a function that sets the instance values of this actor, making this actor instanced</li><li>2: the callback function of this actor</li><li><code>keywords</code>: the keywords of the actor</li><li><code>below</code>: the optional participant below which this actor should be placed. If set, this actor will have the same x coordinate as the given value and the y coordinate of the current position</li><li><code>at</code>: the absolute y position where to create the actor. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li><li><code>margin</code>: horizontal margin between this and the previous actor. Defaults to <code>participantMargin</code></li></ul><p><strong>returns</strong>: The created actor</p><h4 id="instanced-actors" tabindex="-1">Instanced actors <a class="header-anchor" href="#instanced-actors" aria-label="Permalink to “Instanced actors”">​</a></h4><p>An actor can be seen as an <code>instance</code> too if you need it to. In this case, the actor is an <code>instance</code> with a stickman on top. To build an instanced actor, pass the function declaring the instance values as second parameter:</p>`,5),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20user%20%3D%20actor(%22user%22)%20%7B%0A%20%20%20%20%20%20%20%20values%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20age%20%3D%2030%0A%20%20%20%20%20%20%20%20%20%20%20%20isGrownUp%20%3D%20true%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%0A%20%20%20%20instance(%22other%22)%0A%20%20%20%20activate(user)%0A%20%20%20%20activate(other)%0A%20%20%20%20user.after(10)%20--%3E%3E%20other%0A%20%20%20%20deactivate(user%2C%20after%20%3D%2010)%0A%20%20%20%20deactivate(other)%0A%7D%0A`}),c[9]||=i(`p`,null,[o(`The stickman can then be styled/layouted using `),i(`code`,null,`actor-element`),o(`. To access the created instance, use `),i(`code`,null,`<return value>.instance`),o(`.`)],-1),c[10]||=i(`h3`,{id:`component`,tabindex:`-1`},[i(`code`,null,`component`),o(),i(`a`,{class:`header-anchor`,href:`#component`,"aria-label":`Permalink to “component”`},`​`)],-1),c[11]||=i(`p`,null,[o(`Creates a component as a participant, see `),i(`a`,{href:`./component.html#component`},`UML Component Diagram`),o(`:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20component(%22Shop-Frontend%22)%0A%7D%0A`}),c[12]||=i(`h3`,{id:`comment`,tabindex:`-1`},[i(`code`,null,`comment`),o(),i(`a`,{class:`header-anchor`,href:`#comment`,"aria-label":`Permalink to “comment”`},`​`)],-1),c[13]||=i(`p`,null,[o(`Creates a comment, see `),i(`a`,{href:`./class.html#comment`},`UML Class Diagram`),o(`. As a comment is not part of the sequence itself, it is positioned manually:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20activate(A)%0A%20%20%20%20A%20--%3E%20B%0A%20%20%20%20deactivate(A%2C%20after%20%3D%2025)%0A%0A%20%20%20%20comment(%22Only%20called%20for%20new%20orders%22)%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(360%2C%2040)%0A%20%20%20%20%7D%0A%7D%0A`}),c[14]||=i(`h3`,{id:`frame`,tabindex:`-1`},[i(`code`,null,`frame`),o(),i(`a`,{class:`header-anchor`,href:`#frame`,"aria-label":`Permalink to “frame”`},`​`)],-1),c[15]||=i(`p`,null,`Creates a frame, a rectangle containing a section of the diagram, optionally with a text naming it and a subtext for further explanation. To declare a frame, you provide a callback function that contains the interactions within the frame. The frame automatically determines its height based on the current position after the callback executes.`,-1),c[16]||=i(`p`,null,[o(`The frame also `),i(`strong`,null,`automatically determines its width`),o(` by detecting which participants are used within it (through activations, messages, subframes, etc.). You can optionally override this by explicitly specifying `),i(`code`,null,`left`),o(` and `),i(`code`,null,`right`),o(`.`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Alice%22)%0A%20%20%20%20participant(%22Bob%22)%0A%20%20%20%20participant(%22Charlie%22)%0A%0A%20%20%20%20frame(%22while%22%2C%20subtext%20%3D%20%22condition%22)%20%7B%0A%20%20%20%20%20%20%20%20Alice%20--%3E%20Bob%0A%20%20%20%20%7D%0A%7D%0A`}),c[17]||=r(`<p>The frame automatically includes Alice and Bob based on the interactions within it.</p><p><strong>params</strong>:</p><ul><li>0: The text to display in the upper-left corner</li><li>1: A function generating all fragments (additional compartments within the frame)</li><li><code>subtext</code>: The text to display right of the main text, i.e. a condition for an if or while</li><li><code>at</code>: The absolute y position marking the upper border of the frame. If set, takes priority over <code>after</code></li><li><code>after</code>: The relative y offset from the current position for the top border. Only used if <code>at</code> is not set</li><li><code>right</code>: The participant marking the right border of the frame. The border will be extended by <code>marginRight</code> to the right. Optional if a callback is provided</li><li><code>left</code>: The participant marking the left border of the frame. The border will be extended by <code>marginLeft</code> to the left. Optional if a callback is provided</li><li><code>marginLeft</code>: How much margin to use on the left. Defaults to the config <code>frameMarginX</code></li><li><code>marginRight</code>: How much margin to use on the right. Defaults to the config <code>frameMarginX</code></li><li><code>marginBottom</code>: How much margin to use on the bottom. Defaults to the config <code>frameMarginBottom</code></li><li><code>subtextMargin</code>: the horizontal margin for the subtext label. Defaults to the config <code>frameSubtextMargin</code></li></ul><p><strong>returns</strong>: The created frame</p><p>If no callback is provided, you must specify the bottom of the frame with <code>bottomAt</code> or <code>bottomAfter</code>, and its width with <code>left</code> and <code>right</code>.</p><h4 id="fragment" tabindex="-1"><code>fragment</code> <a class="header-anchor" href="#fragment" aria-label="Permalink to “fragment”">​</a></h4><p>A frame can contain multiple fragments. A fragment is a separate section inside the frame, i.e. an <code>else</code> for an <code>if</code> or different parallel branches. Fragments are created by calling the <code>fragment</code> function within the frame&#39;s callback, and are only available there:</p>`,7),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Shop%22)%0A%20%20%20%20participant(%22Payment%22)%0A%0A%20%20%20%20frame(%22alt%22%2C%20subtext%20%3D%20%22cart%20not%20empty%22)%20%7B%0A%20%20%20%20%20%20%20%20Shop%20--%3E%3E%20Payment%0A%20%20%20%20%20%20%20%20fragment(%22else%22%2C%20after%20%3D%2025)%0A%20%20%20%20%20%20%20%20delay(15)%0A%20%20%20%20%20%20%20%20Payment%20--%3E%20Shop%0A%20%20%20%20%7D%0A%7D%0A`}),c[18]||=r(`<p><strong>params</strong>:</p><ul><li>0: The text to display right of the main text, i.e. a condition for an else if</li><li><code>at</code>: the absolute y position where to start the fragment. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li><li><code>subtextMargin</code>: the horizontal margin for the subtext label. Defaults to the config <code>frameSubtextMargin</code></li></ul><p><strong>returns</strong>: The created fragment</p><h4 id="nested-frames" tabindex="-1">Nested frames <a class="header-anchor" href="#nested-frames" aria-label="Permalink to “Nested frames”">​</a></h4><p>You can nest frames by simply placing one frame inside another&#39;s callback function. Both frames will automatically detect their width based on the participants used:</p>`,5),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22alice%22)%0A%20%20%20%20participant(%22bob%22)%0A%20%20%20%20actor(%22Dave%22)%0A%20%20%20%20participant(%22last%22)%0A%0A%20%20%20%20frame(%22outer%22%2C%20marginRight%20%3D%2040)%20%7B%0A%20%20%20%20%20%20%20%20activate(alice%2C%20after%20%3D%2025)%0A%20%20%20%20%20%20%20%20activate(last%2C%20after%20%3D%2025)%0A%20%20%20%20%20%20%20%20destroy(bob)%0A%20%20%20%20%20%20%20%20Cat%20%3D%20participant(%22Cat%22%2C%20below%20%3D%20bob%2C%20after%20%3D%2040)%0A%20%20%20%20%20%20%20%20alice%20--%3E%20Cat%0A%0A%20%20%20%20%20%20%20%20frame(%22if%22%2C%20marginRight%20%3D%2010%2C%20marginBottom%20%3D%2012.4%2C%20subtext%20%3D%20%22finished%22)%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20Dave%20%3C%3C--%20last%20with%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20label(%22notify%22%2C%200.5)%0A%20%20%20%20%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%20%20%20%20%7D%0A%0A%20%20%20%20%20%20%20%20deactivate(alice)%0A%20%20%20%20%20%20%20%20deactivate(last)%0A%20%20%20%20%7D%0A%7D%0A`}),c[19]||=i(`h4`,{id:`manual-frame-width-specification`,tabindex:`-1`},[o(`Manual frame width specification `),i(`a`,{class:`header-anchor`,href:`#manual-frame-width-specification`,"aria-label":`Permalink to “Manual frame width specification”`},`​`)],-1),c[20]||=i(`p`,null,[o(`If you need precise control over which participants are included in a frame, you can manually specify `),i(`code`,null,`left`),o(` and `),i(`code`,null,`right`),o(`. This is useful when you want to include participants that aren't directly interacted with:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Alice%22)%0A%20%20%20%20participant(%22Bob%22)%0A%20%20%20%20participant(%22Charlie%22)%0A%20%20%20%20participant(%22Dave%22)%0A%0A%20%20%20%20%2F%2F%20Frame%20will%20span%20from%20Alice%20to%20Dave%2C%20even%20though%20only%20Bob%20is%20used%0A%20%20%20%20frame(%22note%22%2C%20left%20%3D%20Alice%2C%20right%20%3D%20Dave%2C%20subtext%20%3D%20%22Manual%20width%20control%22)%20%7B%0A%20%20%20%20%20%20%20%20activate(Bob)%0A%20%20%20%20%20%20%20%20deactivate(Bob%2C%20after%20%3D%2025)%0A%20%20%20%20%7D%0A%7D%0A`}),c[21]||=r(`<h4 id="frames-as-per-the-uml-standard" tabindex="-1">Frames as per the UML standard <a class="header-anchor" href="#frames-as-per-the-uml-standard" aria-label="Permalink to “Frames as per the UML standard”">​</a></h4><p>The UML specification recommends the following frames, all of which are created by passing their name as the first argument:</p><ul><li><code>alt</code>: alternatives, one fragment per branch, of which the one whose condition holds is executed. Represents an <code>if</code> / <code>else if</code> / <code>else</code></li><li><code>opt</code>: an optional section, which is only executed if its condition holds. Represents an <code>if</code> without an <code>else</code></li><li><code>loop</code>: a section which is executed as long as its condition holds. Represents a loop, which can be left early with a nested <code>break</code> frame</li><li><code>par</code>: a frame whose fragments are executed in parallel</li><li><code>ref</code>: a reference to another sequence diagram, or to another part of this one. Represents a method call</li></ul>`,3),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Shop%22)%0A%20%20%20%20participant(%22Payment%22)%0A%0A%20%20%20%20frame(%22opt%22%2C%20subtext%20%3D%20%22customer%20subscribed%22)%20%7B%0A%20%20%20%20%20%20%20%20Shop%20--%3E%3E%20Payment%0A%20%20%20%20%7D%0A%7D%0A`}),c[22]||=i(`p`,null,[o(`A `),i(`code`,null,`loop`),o(` frame with a nested `),i(`code`,null,`break`),o(` frame, which leaves the loop when its condition holds:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Shop%22)%0A%20%20%20%20participant(%22Cart%22)%0A%20%20%20%20participant(%22Stock%22)%0A%0A%20%20%20%20frame(%22loop%22%2C%20subtext%20%3D%20%22item%20in%20cart%22)%20%7B%0A%20%20%20%20%20%20%20%20Shop%20--%3E%3E%20Cart%20with%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20label(%22check%22%2C%200.5)%0A%20%20%20%20%20%20%20%20%7D%0A%0A%20%20%20%20%20%20%20%20frame(%22break%22%2C%20subtext%20%3D%20%22item%20unavailable%22%2C%20left%20%3D%20Shop%2C%20right%20%3D%20Stock%2C%20after%20%3D%2015)%0A%0A%20%20%20%20%20%20%20%20delay(20)%0A%20%20%20%20%20%20%20%20Shop%20--%3E%3E%20Stock%20with%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20label(%22reserve%22%2C%200.5)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[23]||=i(`p`,null,[o(`A `),i(`code`,null,`par`),o(` frame, whose fragments are executed in parallel:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Shop%22)%0A%20%20%20%20participant(%22Warehouse%22)%0A%20%20%20%20participant(%22Mail%22)%0A%0A%20%20%20%20frame(%22par%22)%20%7B%0A%20%20%20%20%20%20%20%20Shop%20--%3E%20Warehouse%0A%20%20%20%20%20%20%20%20fragment(after%20%3D%2025)%0A%20%20%20%20%20%20%20%20Shop%20--%3E%20Mail%0A%20%20%20%20%7D%0A%7D%0A`}),c[24]||=i(`p`,null,[o(`A `),i(`code`,null,`ref`),o(` frame, which refers to another sequence diagram:`)],-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Shop%22)%0A%20%20%20%20participant(%22Payment%22)%0A%0A%20%20%20%20frame(%22ref%22%2C%20subtext%20%3D%20%22fraud%20check%22%2C%20left%20%3D%20Shop%2C%20right%20%3D%20Payment)%20%7B%0A%20%20%20%20%20%20%20%20delay(60)%0A%20%20%20%20%7D%0A%7D%0A`}),c[25]||=r(`<h2 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to “Positioning”">​</a></h2><p>The <code>y</code> axis is managed automatically by HyLiMo as you add interactions to your diagram. Each interaction (like <code>activate</code>, message sending, or frame creation) has a margin that determines its vertical spacing:</p><ul><li>By default, each element uses a <strong>configurable margin</strong> that is applied <em>after</em> the element (see <a href="#config-properties">Config properties</a> for available margin settings)</li><li>The actual margin depends on the next declared element - different elements cause different margins to be used</li><li>Use <code>at</code> to specify an <strong>absolute y position</strong>, completely overriding the automatic margin calculation</li><li>Use <code>after</code> to specify a <strong>relative offset</strong> that is <strong>added to</strong> the default margin</li></ul><h3 id="delay-and-moveto" tabindex="-1"><code>delay</code> and <code>moveTo</code> <a class="header-anchor" href="#delay-and-moveto" aria-label="Permalink to “delay and moveTo”">​</a></h3><p><code>delay</code> moves the current position down by a relative offset, <code>moveTo</code> moves it to an absolute y position:</p>`,5),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20A%20--%3E%20B%0A%20%20%20%20delay(60)%0A%20%20%20%20A%20--%3E%20B%0A%20%20%20%20moveTo(200)%0A%20%20%20%20A%20--%3E%20B%0A%7D%0A`}),c[26]||=r(`<p><strong>params</strong>:</p><ul><li>0: the relative y offset from the current position (<code>delay</code>), respectively the absolute y position to move to (<code>moveTo</code>)</li></ul><p><strong>returns</strong>: void</p><h3 id="participant-at-and-participant-after" tabindex="-1"><code>participant.at</code> and <code>participant.after</code> <a class="header-anchor" href="#participant-at-and-participant-after" aria-label="Permalink to “participant.at and participant.after”">​</a></h3><p>Sometimes, you want to send messages at specific positions or with time delays. <code>participant.at(position)</code> creates a virtual participant at an absolute y position, and <code>participant.after(offset)</code> creates one at a relative offset from the current position. Both can be used to create messages to arbitrary points in time:</p>`,5),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Bob%22)%0A%20%20%20%20Bob%20--%3E%20Bob.after(50)%20with%20%7B%0A%20%20%20%20%20%20%20%20over%20%3D%20start().axisAligned(-1%2C%20apos(46%2C%2036)%2C%200%2C%20end(0.5))%0A%20%20%20%20%7D%0A%7D%0A`}),c[27]||=r(`<p><strong>params</strong>:</p><ul><li>0: the absolute y position where to pinpoint the participant (<code>at</code>), respectively the offset from the current position (<code>after</code>). If <code>at</code> is called without a position, the participant itself is used, positioned at its declaring position</li></ul><p><strong>returns</strong>: the new virtual participant to use for i.e. messages</p><h2 id="activity-indicators" tabindex="-1">Activity indicators <a class="header-anchor" href="#activity-indicators" aria-label="Permalink to “Activity indicators”">​</a></h2><p>An activity indicator is the white rectangle on a lifeline marking the time a participant is active. HyLiMo automatically infers where to place the arrow between participants sending/receiving a message: in general, a sent message is sent on the right and a received message is received on the left side of the activity indicator.</p><h3 id="activate" tabindex="-1"><code>activate</code> <a class="header-anchor" href="#activate" aria-label="Permalink to “activate”">​</a></h3><p>Activates an activity indicator at a calculated position:</p>`,7),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20activate(A)%0A%20%20%20%20deactivate(A%2C%20after%20%3D%2025)%0A%7D%0A`}),c[28]||=r(`<p><strong>params</strong>:</p><ul><li>0: the participant (instance or actor) to activate</li><li>1: optional callback function to execute within this activation. After execution, deactivate is called automatically</li><li><code>at</code>: the absolute y position where to activate. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li><li><code>xShift</code>: an optional shift on the x-axis when using multiple activity indicators simultaneously on the same participant. Defaults to <code>activityShift</code></li></ul><p><strong>returns</strong>: The created activity indicator</p><p>You can activate multiple indicators simultaneously for the same participant, using <code>after</code> to add spacing between the activations:</p>`,4),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20activate(A)%0A%20%20%20%20activate(A%2C%20after%20%3D%205)%0A%20%20%20%20deactivate(A%2C%20after%20%3D%2010)%0A%20%20%20%20deactivate(A%2C%20after%20%3D%2020)%0A%7D%0A`}),c[29]||=i(`p`,null,`With the callback function, the indicator is deactivated automatically once the callback has been executed:`,-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20activate(A%2C%20after%20%3D%2025)%20%7B%0A%20%20%20%20%20%20%20%20activate(B)%0A%20%20%20%20%20%20%20%20A%20--%3E%20B%0A%20%20%20%20%20%20%20%20B%20--%3E%20A%0A%20%20%20%20%20%20%20%20deactivate(B)%0A%20%20%20%20%7D%0A%7D%0A`}),c[30]||=r(`<h3 id="deactivate" tabindex="-1"><code>deactivate</code> <a class="header-anchor" href="#deactivate" aria-label="Permalink to “deactivate”">​</a></h3><p>Deactivates the most recent activity indicator of a participant at a calculated position.</p><p><strong>params</strong>:</p><ul><li>0: the participant to deactivate</li><li><code>at</code>: the absolute y position where to deactivate. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li></ul><p><strong>returns</strong>: nothing</p><h2 id="destroying-participants" tabindex="-1">Destroying participants <a class="header-anchor" href="#destroying-participants" aria-label="Permalink to “Destroying participants”">​</a></h2><h3 id="destroy" tabindex="-1"><code>destroy</code> <a class="header-anchor" href="#destroy" aria-label="Permalink to “destroy”">​</a></h3><p>Destroys a participant at a calculated position, which ends its lifeline with a cross:</p>`,8),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20destroy(A)%0A%7D%0A`}),c[31]||=r(`<p><strong>params</strong>:</p><ul><li>0: the participant to destroy</li><li><code>at</code>: the absolute y position where to destroy. If set, takes priority over <code>after</code></li><li><code>after</code>: the relative y offset from the current position. Only used if <code>at</code> is not set</li><li><code>crossSize</code>: the size of the cross to draw. Defaults to <code>destroyingCrossSize</code></li></ul><p><strong>returns</strong>: the created cross</p><p>A destroyed participant can be reanimated by creating a new participant below it:</p>`,4),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20destroy(A)%0A%20%20%20%20participant(%22A%C2%B2%22%2C%20below%20%3D%20A%2C%20after%20%3D%2040)%0A%20%20%20%20delay(20)%0A%7D%0A`}),c[32]||=i(`h2`,{id:`messages`,tabindex:`-1`},[o(`Messages `),i(`a`,{class:`header-anchor`,href:`#messages`,"aria-label":`Permalink to “Messages”`},`​`)],-1),c[33]||=i(`p`,null,`The following messages are available within sequence diagrams (in both directions, of course):`,-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20A%20--%20B%20%2F%2F%20asynchronous%20undirected%20message%0A%20%20%20%20delay(25)%0A%20%20%20%20A%20--%3E%20B%20%2F%2F%20asynchronous%20directed%20message%2C%20object%20creation%20message%0A%20%20%20%20delay(25)%0A%20%20%20%20A%20--%3E%3E%20B%20%2F%2F%20synchronous%20directed%20message%0A%20%20%20%20delay(25)%0A%20%20%20%20A%20%3C..%20B%20%2F%2F%20asynchronous%20return%20message%0A%20%20%20%20delay(25)%0A%20%20%20%20A%20%3C%3C..%20B%20%2F%2F%20synchronous%20return%20message%0A%20%20%20%20delay(25)%0A%20%20%20%20A%20--!%20B%20%2F%2F%20destroy%20message%0A%20%20%20%20delay(25)%0A%20%20%20%20A%20..!%20B%20%2F%2F%20destroy%20return%20message%0A%7D%0A`}),c[34]||=i(`h3`,{id:`labels`,tabindex:`-1`},[o(`Labels `),i(`a`,{class:`header-anchor`,href:`#labels`,"aria-label":`Permalink to “Labels”`},`​`)],-1),c[35]||=i(`p`,null,`Oftentimes, you want to display text on a message. To do this in HyLiMo you can use the following construct (not exclusive to sequence diagrams, works in every other diagram as well):`,-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22A%22)%0A%20%20%20%20participant(%22B%22)%0A%20%20%20%20A%20--%3E%20B%20with%20%7B%0A%20%20%20%20%20%20%20%20label(%22text%22)%20%2F%2F%20positioned%20at%20the%20beginning%20-%200%25%20of%20the%20length%0A%20%20%20%20%7D%0A%20%20%20%20A%20--%3E%20B%20with%20%7B%0A%20%20%20%20%20%20%20%20label(%22text%22%2C%200.5)%20%2F%2F%20positioned%20in%20the%20middle%20-%2050%25%20of%20the%20length%0A%20%20%20%20%7D%0A%20%20%20%20A%20--%3E%20B%20with%20%7B%0A%20%20%20%20%20%20%20%20label(%22text%22%2C%200.75%2C%2010)%20%2F%2F%20positioned%20near%20the%20end%20-%2075%25%20of%20the%20length%2C%2010%20pixels%20upwards%2C%20negative%20values%20are%20possible%20to%20shift%20downward%0A%20%20%20%20%7D%0A%7D%0A`}),c[36]||=i(`h3`,{id:`lostmessage-and-foundmessage`,tabindex:`-1`},[i(`code`,null,`lostMessage`),o(` and `),i(`code`,null,`foundMessage`),o(),i(`a`,{class:`header-anchor`,href:`#lostmessage-and-foundmessage`,"aria-label":`Permalink to “lostMessage and foundMessage”`},`​`)],-1),c[37]||=i(`p`,null,`A lost message is one you sent to a participant not included within the diagram, a found message is one you received from such a participant. Both are exactly the same, the meaning comes from the direction in which you declare the message, and both should always be used inline:`,-1),n(p,{code:`sequenceDiagram%20%7B%0A%20%20%20%20participant(%22Bob%22)%0A%20%20%20%20Bob%20--%3E%3E%20lostMessage()%0A%20%20%20%20delay(25)%0A%20%20%20%20foundMessage()%20--%3E%3E%20Bob%0A%7D%0A`}),c[38]||=r(`<p><strong>params</strong>:</p><ul><li><code>distance</code>: the optional distance of the message on the x axis. Defaults to <code>externalMessageMargin</code></li></ul><p><strong>returns</strong>: The created lost / found message to be used with a message operator</p><h2 id="config-properties" tabindex="-1">Config properties <a class="header-anchor" href="#config-properties" aria-label="Permalink to “Config properties”">​</a></h2><p>The following config properties are available for sequence diagrams:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default value (in pixels)</th><th>Comment</th></tr></thead><tbody><tr><td><code>activityShift</code></td><td>How far on the x axis subsequent simultaneously active activity indicators on the same participant are shifted</td><td>3</td><td>-</td></tr><tr><td><code>activityWidth</code></td><td>How wide an activity indicator should be</td><td>10</td><td>-</td></tr><tr><td><code>minActivityHeight</code></td><td>Minimum height of an activity indicator</td><td>10</td><td>-</td></tr><tr><td><code>strokeMargin</code></td><td>Margin for strokes</td><td>1</td><td>-</td></tr><tr><td><code>connectionMargin</code></td><td>Default distance required after a connection between participants</td><td>20</td><td>-</td></tr><tr><td><code>deactivateMargin</code></td><td>Default distance required after a deactivation</td><td>10</td><td>-</td></tr><tr><td><code>destroyingCrossSize</code></td><td>The width and height of a participant-destruction cross</td><td>20</td><td>-</td></tr><tr><td><code>externalMessageDiameter</code></td><td>Width and height of the circle of lost and found messages</td><td>20</td><td>-</td></tr><tr><td><code>frameMargin</code></td><td>Default distance required after a frame</td><td>20</td><td>-</td></tr><tr><td><code>fragmentMargin</code></td><td>Default distance required after a fragment</td><td>20</td><td>-</td></tr><tr><td><code>externalMessageMargin</code></td><td>How far away on the x axis a lost or found message should be drawn</td><td>95</td><td>100-(0.5*activityWidth), chosen so that it aligns on the grid when sending a message against one activity indicator</td></tr><tr><td><code>frameMarginX</code></td><td>Default margin to apply on the left and right side of frames</td><td>15</td><td>-</td></tr><tr><td><code>frameMarginTop</code></td><td>Default margin to apply on the top of frames</td><td>30</td><td>-</td></tr><tr><td><code>frameMarginBottom</code></td><td>Default margin to apply on the bottom of frames</td><td>5</td><td>-</td></tr><tr><td><code>frameSubtextMargin</code></td><td>Default horizontal margin for frame subtexts</td><td>10</td><td>-</td></tr><tr><td><code>eventDefaultMargin</code></td><td>Default margin for events on a participant when no other margin is specified</td><td>5</td><td>-</td></tr><tr><td><code>participantMargin</code></td><td>How far apart subsequent participants should be</td><td>200</td><td>Multiple of <code>100</code> to align participants on the grid</td></tr><tr><td><code>initialMargin</code></td><td>Default distance required after a new participant</td><td>20</td><td>-</td></tr></tbody></table><h2 id="available-class-names" tabindex="-1">Available class names <a class="header-anchor" href="#available-class-names" aria-label="Permalink to “Available class names”">​</a></h2><p>The following class names are available for styling/layout purposes within sequence diagrams:</p><ul><li><code>activity-indicator-element</code> to layout activity indicator elements</li><li><code>activity-indicator</code> to style activity indicators</li><li><code>actor-element</code> to layout actors</li><li><code>actor</code> to style actors</li><li><code>destroy-cross-path-element</code> to layout the cross of a destroyed participant</li><li><code>destroy-cross-path</code> to style the cross of a destroyed participant</li><li><code>found-message-element</code> to layout found message elements</li><li><code>found-message</code> to style found messages</li><li><code>fragment-name-border</code> to style the border around fragment names</li><li><code>fragment-name-element</code> to layout both the border and name of fragments</li><li><code>fragment-name</code> to style the text display of fragment names</li><li><code>fragment-subtext-element</code> to layout the subtext of fragments</li><li><code>fragment-subtext</code> to style the subtext of fragments</li><li><code>frame-element</code> to layout the subtext of frames</li><li><code>frame</code> to style frames</li><li><code>instance-element</code> to layout instances</li><li><code>instance</code> to style instances</li><li><code>lost-message-element</code> to layout lost message elements</li><li><code>lost-message</code> to style lost messages</li><li><code>non-top-level-participant-element</code> to style any participant created after the position has moved, so its <code>y</code> is not <code>0</code></li><li><code>participant-element</code> to layout participants</li><li><code>participant</code> to style participants</li><li><code>top-level-participant-element</code> to style any participant created at the initial position, so its <code>y</code> is <code>0</code></li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p>Here is an example for a webshop order, using most of the features described above:</p>`,11),n(m,{id:`sequence`})])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};